#!/usr/bin/env python3
from pathlib import Path

p = Path("index.html")
if not p.exists():
    raise SystemExit("ERROR: index.html not found. Run this inside your website folder.")

html = p.read_text(encoding="utf-8")
css = "\n    /* PODATURPET MANUFACTURER AD */\n    .manufacturer-ad{\n      background:linear-gradient(135deg,#f8f3e9 0%,#fff 52%,#f4ead7 100%);\n      padding:70px 0;\n      border-top:1px solid rgba(7,27,23,.08);\n      border-bottom:1px solid rgba(7,27,23,.08);\n    }\n    .manufacturer-ad-wrap{\n      display:grid;\n      grid-template-columns:1.05fr .95fr;\n      gap:42px;\n      align-items:stretch;\n    }\n    .manufacturer-ad-copy{\n      background:#fff;\n      border:1px solid rgba(7,27,23,.08);\n      border-radius:26px;\n      padding:44px;\n      box-shadow:0 18px 50px rgba(7,27,23,.09);\n    }\n    .manufacturer-kicker{\n      display:inline-flex;align-items:center;gap:8px;padding:8px 12px;border-radius:999px;\n      background:#0b2b23;color:#f2c45a;font-size:.76rem;font-weight:900;letter-spacing:.08em;\n      text-transform:uppercase;margin-bottom:20px\n    }\n    .manufacturer-ad h2{\n      margin:0;color:#0b2b23;font-size:clamp(2.6rem,5vw,5rem);line-height:.98;letter-spacing:-.045em\n    }\n    .manufacturer-ad h2 span{color:#c9952f}\n    .manufacturer-lead{margin:22px 0 0;color:#34443e;font-size:1.08rem;line-height:1.75;max-width:720px}\n    .manufacturer-lead strong{color:#0b2b23}\n    .manufacturer-promise{\n      margin:24px 0 0;padding:18px 20px;border-left:4px solid #d4a23d;background:#fbf6eb;\n      border-radius:0 14px 14px 0;color:#0b2b23;font-weight:800;line-height:1.55\n    }\n    .manufacturer-points{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin:26px 0 0}\n    .manufacturer-point{padding:16px;border-radius:14px;background:#f7f3ea;border:1px solid rgba(7,27,23,.08)}\n    .manufacturer-point strong{display:block;color:#0b2b23;margin-bottom:4px;font-size:.96rem}\n    .manufacturer-point span{color:#66736e;font-size:.88rem;line-height:1.45}\n    .manufacturer-cta{display:flex;flex-wrap:wrap;gap:12px;margin-top:28px}\n    .manufacturer-cta a{\n      display:inline-flex;align-items:center;justify-content:center;min-height:48px;padding:0 20px;\n      border-radius:12px;font-weight:900;text-decoration:none\n    }\n    .manufacturer-cta .primary{background:#e3b23c;color:#071b17;box-shadow:0 10px 22px rgba(227,178,60,.24)}\n    .manufacturer-cta .secondary{background:#0b2b23;color:#fff}\n    .manufacturer-ad-visual{\n      position:relative;min-height:100%;border-radius:26px;overflow:hidden;\n      background:linear-gradient(180deg,rgba(5,24,20,.08),rgba(5,24,20,.35)),\n                 url('images/podaturpet-manufacturer-ad.png') center top/cover no-repeat;\n      box-shadow:0 18px 50px rgba(7,27,23,.16);border:1px solid rgba(7,27,23,.10)\n    }\n    .manufacturer-badge{\n      position:absolute;right:20px;bottom:20px;width:min(290px,calc(100% - 40px));\n      background:rgba(7,27,23,.94);color:#fff;border:1px solid rgba(227,178,60,.45);\n      border-radius:18px;padding:20px;backdrop-filter:blur(8px)\n    }\n    .manufacturer-badge small{\n      display:block;color:#e3b23c;font-weight:900;text-transform:uppercase;letter-spacing:.11em;margin-bottom:6px\n    }\n    .manufacturer-badge strong{display:block;font-size:1.35rem;line-height:1.18;margin-bottom:6px}\n    .manufacturer-badge span{color:#d9e2de;font-size:.9rem;line-height:1.45}\n    @media(max-width:900px){\n      .manufacturer-ad{padding:44px 0}\n      .manufacturer-ad-wrap{grid-template-columns:1fr}\n      .manufacturer-ad-copy{padding:30px}\n      .manufacturer-ad-visual{min-height:520px}\n    }\n    @media(max-width:560px){\n      .manufacturer-ad-copy{padding:24px}\n      .manufacturer-points{grid-template-columns:1fr}\n      .manufacturer-ad-visual{min-height:430px}\n      .manufacturer-cta a{width:100%}\n    }\n"
section = '\n<section class="manufacturer-ad" id="direct-manufacturer">\n  <div class="container manufacturer-ad-wrap">\n    <div class="manufacturer-ad-copy">\n      <div class="manufacturer-kicker">Direct from Podaturpet • Wholesale Ready</div>\n      <h2>We weave. We deliver. <span>You grow.</span></h2>\n\n      <p class="manufacturer-lead">\n        We work directly from the Podaturpet textile region to supply quality lungis for\n        retailers, distributors and wholesale buyers. <strong>Our goal is simple:</strong>\n        dependable quality, fair wholesale pricing and a business relationship you can trust.\n      </p>\n\n      <div class="manufacturer-promise">\n        Give us one opportunity. Try our lungis once, check the quality yourself,\n        and then decide your next bulk order.\n      </div>\n\n      <div class="manufacturer-points">\n        <div class="manufacturer-point">\n          <strong>Direct Manufacturing Connection</strong>\n          <span>Closer to the weaving source with fewer unnecessary layers.</span>\n        </div>\n        <div class="manufacturer-point">\n          <strong>Quality-Focused Lungis</strong>\n          <span>Cotton, handloom and powerloom options for different markets.</span>\n        </div>\n        <div class="manufacturer-point">\n          <strong>Bulk Orders Welcome</strong>\n          <span>Buyer enquiries for shops, distributors and larger requirements.</span>\n        </div>\n        <div class="manufacturer-point">\n          <strong>India + Worldwide</strong>\n          <span>We welcome enquiries from domestic and international buyers.</span>\n        </div>\n      </div>\n\n      <div class="manufacturer-cta">\n        <a class="primary"\n           href="https://wa.me/14793201970?text=Hello%20Murali%2C%20I%20want%20to%20try%20Podaturpet%20lungis.%20Please%20send%20wholesale%20details%20and%20pricing."\n           target="_blank" rel="noopener noreferrer">\n          Give Us a Chance — Get Wholesale Quote\n        </a>\n        <a class="secondary" href="#international-buyers">International Buyers</a>\n      </div>\n    </div>\n\n    <div class="manufacturer-ad-visual" role="img"\n         aria-label="Podaturpet lungi manufacturing and wholesale buyer promotion">\n      <div class="manufacturer-badge">\n        <small>Woven Trust</small>\n        <strong>Tradition in every thread. Trust in every order.</strong>\n        <span>Quality you can feel. Service you can trust.</span>\n      </div>\n    </div>\n  </div>\n</section>\n'

if "/* PODATURPET MANUFACTURER AD */" not in html:
    if "</style>" not in html:
        raise SystemExit("ERROR: closing style tag not found.")
    html = html.replace("</style>", css + "\n  </style>", 1)

if 'id="direct-manufacturer"' not in html:
    marker = '<section class="buyer-assurance"'
    idx = html.find(marker)
    if idx != -1:
        html = html[:idx] + section + "\n" + html[idx:]
    else:
        hero_idx = html.find('class="hero"')
        close_idx = html.find("</section>", hero_idx)
        if close_idx == -1:
            raise SystemExit("ERROR: could not find a safe insertion point.")
        close_idx += len("</section>")
        html = html[:close_idx] + "\n" + section + html[close_idx:]

p.write_text(html, encoding="utf-8")
print("DONE: manufacturer buyer-attraction ad added to homepage.")
print("Next:")
print("git add index.html images/podaturpet-manufacturer-ad.png")
print('git commit -m "Add direct manufacturer wholesale campaign"')
print("git push")
